"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["986"],{779(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/taurus/overview","label":"Overview","docId":"Overview","unlisted":false},{"type":"link","href":"/taurus/installation","label":"Installation","docId":"installation/installation","unlisted":false},{"type":"category","label":"Configure","collapsible":false,"items":[{"type":"link","href":"/taurus/configure","label":"Variables","docId":"configure/Configure","unlisted":false},{"type":"link","href":"/taurus/configure/scenes","label":"Scenes","docId":"configure/Scenes","unlisted":false},{"type":"link","href":"/taurus/configure/recovery","label":"Self-healing","docId":"configure/Recovery","unlisted":false},{"type":"link","href":"/taurus/configure/share","label":"Share your setup","docId":"configure/Share","unlisted":false},{"type":"category","label":"Compositors","collapsible":false,"items":[{"type":"link","href":"/taurus/configure/compositors/hyprland","label":"Hyprland","docId":"configure/compositors/hyprland","unlisted":false},{"type":"link","href":"/taurus/configure/compositors/niri","label":"Niri","docId":"configure/compositors/niri","unlisted":false},{"type":"link","href":"/taurus/configure/compositors/sway","label":"Sway","docId":"configure/compositors/sway","unlisted":false},{"type":"link","href":"/taurus/configure/compositors/mango","label":"Mango","docId":"configure/compositors/mango","unlisted":false},{"type":"link","href":"/taurus/configure/compositors/umbriel","label":"Umbriel","docId":"configure/compositors/umbriel","unlisted":false}],"collapsed":false}],"collapsed":false},{"type":"category","label":"AI","collapsible":false,"items":[{"type":"link","href":"/taurus/ai/agents","label":"AI agents","docId":"ai/agents","unlisted":false}],"collapsed":false},{"type":"category","label":"Components","collapsible":false,"items":[{"type":"link","href":"/taurus/audio","label":"taurus-audio","docId":"components/taurus-audio","unlisted":false},{"type":"link","href":"/taurus/core","label":"taurus-core","docId":"components/taurus-core","unlisted":false},{"type":"link","href":"/taurus/gamma","label":"taurus-gamma","docId":"components/taurus-gamma","unlisted":false}],"collapsed":false},{"type":"category","label":"CLI","collapsible":false,"items":[{"type":"link","href":"/taurus/cli/client","label":"Taurus client","docId":"cli/client","unlisted":false},{"type":"link","href":"/taurus/cli/daemon","label":"Taurus daemon","docId":"cli/daemon","unlisted":false}],"collapsed":false}]},"docs":{"ai/agents":{"id":"ai/agents","title":"AI agents","description":"Taurus ships skills the agent gets a stable, self-documenting command (taurus), a map of where everything lives, and a short list of rules, so it changes your setup the way you would.","sidebar":"tutorialSidebar"},"cli/client":{"id":"cli/client","title":"Taurus client","description":"taurus is the command-line client for the desktop shell.","sidebar":"tutorialSidebar"},"cli/daemon":{"id":"cli/daemon","title":"Taurus daemon","description":"taurusd is the background service daemon for the desktop shell.","sidebar":"tutorialSidebar"},"components/taurus-audio":{"id":"components/taurus-audio","title":"taurus-audio","description":"Taurus ships its own small audio processor, taurus-audio. It replaces EasyEffects and depends only on PipeWire. The equalizer, balance, mono, channel swap, dynamic range modes and the dynamic EQ in the music popup all run on it.","sidebar":"tutorialSidebar"},"components/taurus-core":{"id":"components/taurus-core","title":"taurus-core","description":"Taurus ships a small background service written in Rust, taurus-core. It serves system usage, compositor state, brightness, idle inhibition, screen time, launcher ranking and clipboard history to the shell. These used to be scripts and Python helpers that the shell ran on a timer or on every event. Now one long-running process answers them, so the shell no longer starts a process for each poll and no longer needs brightnessctl or python-jeepney.","sidebar":"tutorialSidebar"},"components/taurus-gamma":{"id":"components/taurus-gamma","title":"taurus-gamma","description":"Taurus ships its own blue light filter, taurus-gamma. It sets the color temperature, brightness, gamma and inversion of your displays on Wayland, with a day and night schedule that follows the sun.","sidebar":"tutorialSidebar"},"configure/AppTheming":{"id":"configure/AppTheming","title":"App theming","description":"Taurus can recolor other apps with the same palette as the shell, whether it comes from the wallpaper (Matugen) or from a preset. Open Settings \u2192 Theme \u2192 App theming. The page lists the apps that are currently themed. Add another one from Add app, or remove one with the delete button on its tile."},"configure/compositors/hyprland":{"id":"configure/compositors/hyprland","title":"Hyprland","description":"Configuration is stored in ~/.config/hypr. The main file is hyprland.lua, which loads modules from the config/ directory:","sidebar":"tutorialSidebar"},"configure/compositors/mango":{"id":"configure/compositors/mango","title":"Mango","description":"Configuration is stored in ~/.config/mango. The main file is config.conf, which includes modular files from config/:","sidebar":"tutorialSidebar"},"configure/compositors/niri":{"id":"configure/compositors/niri","title":"Niri","description":"Configuration is stored in ~/.config/niri. The main file is config.kdl, which includes files from the config/ directory:","sidebar":"tutorialSidebar"},"configure/compositors/sway":{"id":"configure/compositors/sway","title":"Sway","description":"Configuration is stored in ~/.config/sway. The main file is config, which includes modular files from configDir/:","sidebar":"tutorialSidebar"},"configure/compositors/umbriel":{"id":"configure/compositors/umbriel","title":"Umbriel","description":"Configuration is stored in ~/.config/umbriel. The main file is config.toml, which includes modular files from config/:","sidebar":"tutorialSidebar"},"configure/Configure":{"id":"configure/Configure","title":"Variables","description":"The configuration file is located at ~/.config/taurus/settings.json (or ${XDGCONFIGHOME:-$HOME/.config}/taurus/settings.json), and changes apply instantly without a reload.","sidebar":"tutorialSidebar"},"configure/Recovery":{"id":"configure/Recovery","title":"Self-healing","description":"Taurus checks itself and repairs the few things that can be repaired safely. Nothing here needs you to do anything; this page explains what happens and how to check it by hand.","sidebar":"tutorialSidebar"},"configure/Scenes":{"id":"configure/Scenes","title":"Scenes","description":"A scene is a named bundle of settings that switch together: do not disturb, dock and bar autohide, interface sounds, caffeine, the theme and the screen warmth. Switch one by hand, or let Taurus switch it for you when a game is focused or the evening starts.","sidebar":"tutorialSidebar"},"configure/Share":{"id":"configure/Share","title":"Share your setup","description":"Export what makes your Taurus yours into one file, send it to someone, and let them preview and import it.","sidebar":"tutorialSidebar"},"installation/installation":{"id":"installation/installation","title":"Installation","description":"Migrating from v1: All previous configuration will be backed up and unused. Configuration of compositor settings such as monitors, keybinds, and autostart is now up to you, as the project migrated from being dotfiles to being a shell.","sidebar":"tutorialSidebar"},"Overview":{"id":"Overview","title":"Overview","description":"Taurus Banner","sidebar":"tutorialSidebar"}}}}')}}]);